'use client';

import * as React from 'react';
import * as SelectPrimitive from '@radix-ui/react-select';
import { CheckIcon, ChevronDownIcon } from './icons';
import { cn } from '@/lib/utils';

export const Select = SelectPrimitive.Root;
export const SelectGroup = SelectPrimitive.Group;
export const SelectValue = SelectPrimitive.Value;

export const SelectTrigger = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger>
>(({ className, children, ...props }, ref) => (
  <SelectPrimitive.Trigger
    ref={ref}
    className={cn(
      'flex h-(--control-h) w-full items-center justify-between gap-2 rounded-md border border-input bg-background px-3 text-sm outline-none transition-[border,box-shadow] hover:border-muted-foreground/40 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/15 disabled:opacity-50 data-[placeholder]:text-muted-foreground/70 [&>span]:truncate',
      className,
    )}
    {...props}
  >
    {children}
    <SelectPrimitive.Icon asChild>
      <ChevronDownIcon className="size-4 shrink-0 text-muted-foreground" />
    </SelectPrimitive.Icon>
  </SelectPrimitive.Trigger>
));
SelectTrigger.displayName = 'SelectTrigger';

export const SelectContent = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Content>
>(({ className, children, position = 'popper', ...props }, ref) => (
  <SelectPrimitive.Portal>
    <SelectPrimitive.Content
      ref={ref}
      position={position}
      sideOffset={6}
      className={cn(
        'z-50 max-h-72 min-w-[8rem] overflow-hidden rounded-lg border bg-popover p-1 text-popover-foreground shadow-lg animate-pop',
        position === 'popper' && 'w-[var(--radix-select-trigger-width)]',
        className,
      )}
      {...props}
    >
      <SelectPrimitive.Viewport>{children}</SelectPrimitive.Viewport>
    </SelectPrimitive.Content>
  </SelectPrimitive.Portal>
));
SelectContent.displayName = 'SelectContent';

export const SelectLabel = ({ className, ...props }: React.ComponentPropsWithoutRef<typeof SelectPrimitive.Label>) => (
  <SelectPrimitive.Label className={cn('px-2 py-1.5 text-[11px] font-medium uppercase tracking-wider text-muted-foreground', className)} {...props} />
);

export const SelectItem = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Item>
>(({ className, children, ...props }, ref) => (
  <SelectPrimitive.Item
    ref={ref}
    className={cn(
      'relative flex cursor-pointer select-none items-center rounded-md py-1.5 pl-2 pr-8 text-sm outline-none data-[disabled]:opacity-50 data-[highlighted]:bg-secondary',
      className,
    )}
    {...props}
  >
    <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
    <SelectPrimitive.ItemIndicator className="absolute right-2">
      <CheckIcon className="size-4 text-primary" />
    </SelectPrimitive.ItemIndicator>
  </SelectPrimitive.Item>
));
SelectItem.displayName = 'SelectItem';

import 'package:flutter/material.dart';

import 'dropdown_menu.dart';
import 'icons.dart';
import 'theme.dart';

class BefSelectOption<T> {
  const BefSelectOption({required this.value, required this.label});
  final T value;
  final String label;
}

/// A dropdown that looks like an input: pick one option from a list.
class BefSelect<T> extends StatefulWidget {
  const BefSelect({
    super.key,
    required this.options,
    required this.value,
    required this.onChanged,
    this.placeholder = 'Select...',
    this.enabled = true,
  });
  final List<BefSelectOption<T>> options;
  final T? value;
  final ValueChanged<T> onChanged;
  final String placeholder;
  final bool enabled;

  @override
  State<BefSelect<T>> createState() => _BefSelectState<T>();
}

class _BefSelectState<T> extends State<BefSelect<T>> {
  bool _hover = false;

  @override
  Widget build(BuildContext context) {
    final c = context.bef;
    final selected = widget.options.where((o) => o.value == widget.value).firstOrNull;
    return LayoutBuilder(
      builder: (context, box) {
        return MenuAnchor(
          style: befMenuStyle(context, minWidth: box.maxWidth.isFinite ? box.maxWidth : 160),
          alignmentOffset: const Offset(0, 6),
          menuChildren: [
            for (final o in widget.options)
              MenuItemButton(
                // the panel is as wide as its widest item, so the items are what make the menu as wide as the field
                style: befMenuItemStyle(context).copyWith(
                  minimumSize: WidgetStatePropertyAll(
                    Size(box.maxWidth.isFinite ? box.maxWidth - 8 : 152, 34),
                  ),
                ),
                leadingIcon: SizedBox(
                  width: 16,
                  child: o.value == widget.value
                      ? BefIcon(BefIcons.check, size: 14, color: c.primary, weight: 2.5)
                      : null,
                ),
                onPressed: () => widget.onChanged(o.value),
                child: Text(o.label),
              ),
          ],
          builder: (context, controller, _) => Opacity(
            opacity: widget.enabled ? 1 : 0.5,
            child: MouseRegion(
              onEnter: (_) => setState(() => _hover = true),
              onExit: (_) => setState(() => _hover = false),
              child: Semantics(
                button: true,
                enabled: widget.enabled,
                label: selected?.label ?? widget.placeholder,
                child: GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: widget.enabled
                      ? () => controller.isOpen ? controller.close() : controller.open()
                      : null,
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 150),
                    height: 36,
                    padding: const EdgeInsets.symmetric(horizontal: 12),
                    decoration: BoxDecoration(
                      color: c.background,
                      borderRadius: BorderRadius.circular(BefRadius.md),
                      border: Border.all(
                        color: controller.isOpen
                            ? c.ring
                            : (_hover ? c.mutedForeground.withValues(alpha: 0.4) : c.input),
                      ),
                      boxShadow: controller.isOpen
                          ? [BoxShadow(color: c.ring.withValues(alpha: 0.15), spreadRadius: 3)]
                          : null,
                    ),
                    child: Row(
                      children: [
                        Expanded(
                          child: Text(
                            selected?.label ?? widget.placeholder,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: BefText.style(
                              context,
                              color: selected == null ? c.mutedForeground : c.foreground,
                            ),
                          ),
                        ),
                        const SizedBox(width: 8),
                        BefIcon(BefIcons.chevronDown, size: 16, color: c.mutedForeground),
                      ],
                    ),
                  ),
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

